 void Rect(RectTransform r,float x,float y,float w,float h){Vector2 anchor=new Vector2(.5f,.5f);if(r.parent==safeFrame){if(y>=350){anchor=new Vector2(.5f,1);y-=468;}else if(y<-200){anchor=new Vector2(x<-400?0:x>400?1:.5f,0);y+=468;if(x<-400)x+=818;else if(x>400)x-=818;}}r.anchorMin=r.anchorMax=anchor;r.anchoredPosition=new Vector2(x,y);r.sizeDelta=new Vector2(w,h);}
