 public void ApplySafeArea(){var cam=match.player.playerCamera;var viewport=cam.pixelRect;if(viewport.width<=0||viewport.height<=0)return;var area=cam.targetTexture!=null?viewport:Screen.safeArea;safeFrame.anchorMin=new Vector2(Mathf.Clamp01((area.xMin-viewport.xMin)/viewport.width),Mathf.Clamp01((area.yMin-viewport.yMin)/viewport.height));safeFrame.anchorMax=new Vector2(Mathf.Clamp01((area.xMax-viewport.xMin)/viewport.width),Mathf.Clamp01((area.yMax-viewport.yMin)/viewport.height));safeFrame.offsetMin=safeFrame.offsetMax=Vector2.zero;}
